// Регресс «готовность к выпуску 19.10.2026» — группа 4: профиль.
// Факты: ac-status.md «Дополнение 19.10» (F-46 AC4, F-36 AC3, F-44 AC6 Longyearbyen 19.12.2026), readiness-report.html («Профиль»,
// «Риск App Store», тикет #693450a9), снимки app/F-46-profile.txt (строки «<поле>: <значение>. מעבר לשלב כדי לשנות»),
// F-44-longyearbyen*.txt, S-27-prayers.txt, F-93-brachot.txt. F-50 AC3 (קבלה после перезапуска) — уже JR-04, не дублируется.
// Всё, что меняется, возвращается в finally (нусах, согласие, город). Кейсы: .qa/tests/readiness/RD-04-profile.md.
import { expect } from '@wdio/globals';
import { byText, byTextContains, byLabelStartsWith, scrollToText } from '../../helpers/ui.ts';
import { goTab } from '../../helpers/nav.ts';
import { shown } from '../_lib/app-0710.ts';
import {
  goHome, openProfile, profileValue, withProfileNusach, saveProfileStep, button, openCatalog, catalogCard, labelOf,
  openCatalogPrayer, shownNusach, setProfileCity, openZmanim, zmanimGoTo, zmanimDate, zmanimRows, nodes,
} from '../_lib/readiness-1910.ts';

const CONSENT_ROW = 'הודעות במייל, SMS ו־WhatsApp';
const CONSENT_BOX = 'אני מאשר לקבל התראות למייל';
const NOT_SENT = 'עדיין אינן נשלחות';

async function consentValue() {
  await openProfile();
  await scrollToText(CONSENT_ROW);
  return profileValue(CONSENT_ROW);
}
/** Окно согласия: переключить галочку → «שמירה» → «השינוי נשמר». */
async function toggleConsent() {
  await (await byLabelStartsWith(`${CONSENT_ROW}: `)).click();
  const box = await byLabelStartsWith(CONSENT_BOX);
  await box.waitForDisplayed({ timeout: 15000 });
  await box.click();
  await saveProfileStep();
}

describe('Готовность 19.10 — профиль', () => {
  afterEach(async () => { await goHome().catch(() => {}); });

  it('RD-04a נוסח профиля «ספרד» → «נוסח ספרד» на «בית», «בנוסח ספרד» на «תפילות» и «ברכות», карточки «נוסח התפילה ספרדי», молитва «ספרדי»; затем «אשכנז» назад F-46 AC4 @data', async function () {
    this.timeout(600000);
    await withProfileNusach('ספרד', async () => {
      await goHome();
      await expect(byText('נוסח ספרד')).toBeDisplayed({ wait: 20000 });
      await openCatalog();
      await expect(byTextContains('התפילות מוצגות בנוסח ספרד')).toBeDisplayed();
      expect(await labelOf((await catalogCard('שחרית')) as unknown as WebdriverIO.Element)).toContain('נוסח התפילה ספרדי');
      await goHome();
      await goTab('ברכות');
      await expect(byTextContains('בנוסח ספרד')).toBeDisplayed({ wait: 20000 });
      await openCatalogPrayer('מנחה');
      expect(await shownNusach()).toBe('ספרדי');
    });
    // withProfileNusach уже проверил «נוסח אשכנז» на главной; каталог тоже в אשכנז.
    await openCatalog();
    await expect(byTextContains('התפילות מוצגות בנוסח אשכנז')).toBeDisplayed();
  });

  it('RD-04b Согласие на рассылку: вкл → «השינוי נשמר», строка «מאושר»; выкл → «לא מאושר» (исходное значение возвращено) F-36 AC3 @data', async () => {
    const orig = await consentValue();
    try {
      await toggleConsent();
      const v1 = await consentValue();
      expect(v1).not.toBe(orig);
      await toggleConsent();
      expect(await consentValue()).toBe(orig);
    } finally {
      if ((await consentValue()) !== orig) await toggleConsent();
      expect(await consentValue()).toBe(orig);
    }
    expect(['לא מאושר', 'מאושר']).toContain(orig);
  });

  it('RD-04c Окно согласия не обещает, что рассылка не отправляется: нет «…עדיין אינן נשלחות» #693450a9 @known-bug @prod-safe', async () => {
    await consentValue();
    await (await byLabelStartsWith(`${CONSENT_ROW}: `)).click();
    await (await byLabelStartsWith(CONSENT_BOX)).waitForDisplayed({ timeout: 15000 });
    const notSent = await shown(byTextContains(NOT_SENT));
    await (await button('סגירה')).click().catch(() => {});
    // 19.10: «הודעות במייל, ב־SMS וב־WhatsApp עדיין אינן נשלחות.» — рассылка не работает даже с согласием.
    expect(notSent).toBe(false);
  });

  it('RD-04d Город без расчёта: Longyearbyen, 19.12.2026 («ט׳ טבת תשפ״ז») — «—» и «לא ניתן לחשב ביום זה», «השמש אינה יורדת מספיק…»; исходный город возвращён F-44 AC6 @data', async function () {
    this.timeout(900000);
    await openProfile();
    await scrollToText('מיקום');
    const orig = await profileValue('מיקום');
    try {
      await setProfileCity('Longyearbyen');
      await openZmanim();
      await expect(byTextContains('הזמנים חושבו עבור Longyearbyen')).toBeDisplayed({ wait: 20000 });
      await zmanimGoTo(2026, 12, 19);
      expect((await zmanimDate()).heb).toBe('ט׳ טבת תשפ״ז');
      const rows = await zmanimRows();
      const dash = rows.filter((r) => r.time === '—');
      console.log(`[RD-04d] строк «—»: ${dash.length} из ${rows.length}`);
      expect(dash.length).toBeGreaterThan(0);
      expect(rows.find((r) => r.name === 'נץ החמה')?.time).toBe('—');
      expect(rows.find((r) => r.name === 'שקיעת החמה')?.time).toBe('—');
      const all = (await nodes()).map((n) => n.label).join('\n');
      expect(all).toContain('לא ניתן לחשב ביום זה');
      expect(all).toContain('השמש אינה יורדת מספיק');
    } finally {
      await setProfileCity(orig);
      await openZmanim();
      await expect(byTextContains(`הזמנים חושבו עבור ${orig}`)).toBeDisplayed({ wait: 20000 });
    }
  });

  it('RD-04e В профиле есть удаление аккаунта «מחיקת חשבון» (App Store 5.1.1(v)) #b7295677 @prod-safe @passed-2110', async () => {
    await openProfile();
    await scrollToText('התנתקות');
    const all = (await nodes()).map((n) => n.label).join('\n');
    // 19.10: только «התנתקות»; 21.10 (#b7295677 עבר QA): «מחיקת חשבון» под «התנתקות». Окно и «ביטול» — qa-2110/q-10.
    expect(all).toContain('מחיקת חשבון');
  });
});
